def rle_encode(text):
    """Run-length encoding: WWWWBBB becomes 4W3B."""
    out, i = "", 0
    while i < len(text):
        run = 1
        while i + run < len(text) and text[i + run] == text[i]:
            run += 1
        out += f"{run}{text[i]}"
        i += run
    return out

for row in ["WWWWWWWWWWWWBBBWWWWWWWWWWWW", "WBWBWBWBWBWB", "hello world"]:
    packed = rle_encode(row)
    print(f"{row:<28} -> {packed:<26} {len(row):>2} chars -> {len(packed):>2}")

import random, sysconfig, zlib, pathlib

samples = {
    "Python source code": pathlib.Path(sysconfig.get_paths()["stdlib"], "os.py").read_bytes(),
    "the same line 2,000 times": b"The quick brown fox jumps over the lazy dog.\n" * 2000,
    "random bytes": random.Random(42).randbytes(100_000),
}
for name, data in samples.items():
    packed = zlib.compress(data, 9)
    assert zlib.decompress(packed) == data          # lossless: exactly the same back
    print(f"{name:<26} {len(data):>7,} -> {len(packed):>6,} bytes  ({len(packed) / len(data):.2%} of original)")
